// Writes sources-more.json: the second half of the script corpus (snippets in the shape of the tools' documentation and of real
// collections: tests, token extraction, request chaining, signing, flow control). Plain data; run `node make-more.mjs` to rewrite it.
// The corpus test (tests/unit/script-convert-v2.test.ts) converts each, freezes the output (expected-more.json), checks every conversion is
// idempotent, and, where the original runs offline, that the same tests pass and the same variables are set.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const out = { postman: [], insomnia: [], bruno: [], thunder: [], hoppscotch: [] };
const add = (tool, name, source) => out[tool].push({ name, source });

/* ------------------------------------------------------------------ Postman */
for (const code of [201, 202, 204, 301, 400, 401, 403, 404, 409, 422, 429, 500]) add('postman', `status ${code} expected`, `pm.test("Status code is ${code}", function () {\n    pm.response.to.have.status(${code});\n});`);
for (const ms of [100, 300, 500, 1000, 2000]) add('postman', `response under ${ms} ms`, `pm.test("Response time is under ${ms}ms", () => {\n    pm.expect(pm.response.responseTime).to.be.below(${ms});\n});`);
for (const h of ['Content-Type', 'Cache-Control', 'X-Request-Id', 'ETag']) add('postman', `has header ${h}`, `pm.test("${h} header is present", function () {\n    pm.response.to.have.header("${h}");\n});`);
add('postman', 'content type includes json', `pm.test("JSON content type", () => {\n    pm.expect(pm.response.headers.get("Content-Type")).to.include("json");\n});`);
