add('postman', 'body contains text', `pm.test("body mentions n", () => {\n    pm.expect(pm.response.text()).to.include("n");\n});`);
add('postman', 'body matches regex', `pm.test("token is word chars", () => {\n    pm.expect(pm.response.json().token).to.match(/^\\w+$/);\n});`);
add('postman', 'response is ok shortcut', `pm.test("ok", () => {\n    pm.response.to.be.ok;\n});`);
